import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class PlanGenerate(GenericEMSSIMCommand):
    """Plangenerate command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Plangenerate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(PlanGenerate, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.current_key = "FILE_CONTENT_INFO"
        self.current_ret["FILE_CONTENT_INFO"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "plan_generate"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_result(line)
                self._find_managed_object(line)
                self._parse_attributes(line)
            except ParsingDone:
                pass
        return super(PlanGenerate, self).on_new_line(line, is_full_line)

    _re_info_line = re.compile(r"(?P<LINE>Generated\sxml\sdelta\sfile:.*)")

    def _parse_result(self, line):
        if self._regex_helper.search_compiled(PlanGenerate._re_info_line, line):
            self.current_ret["RESULT"] = self._regex_helper.group("LINE")
            raise ParsingDone

    _re_attributes_list = []
    _re_attributes_list.append(re.compile(r"<p\sname=\"(?P<ATTR>[^\"]+)\">(?P<VALUE>[^<]+)</p>"))
    _re_attributes_list.append(re.compile(r"[<]?[p\s]?\s*(?P<ATTR>[^=\"|<>]+)=\"(?P<VALUE>[^\"<>]+)\""))

    def _parse_attributes(self, line):
        for re_attribute in PlanGenerate._re_attributes_list:
            if self._regex_helper.search_compiled(re_attribute, line):
                attributes = re.findall(re_attribute, line)
                if self.current_key in self.current_ret:
                    self.current_ret[self.current_key].update(dict(attributes))
                else:
                    self.current_ret[self.current_key] = dict(attributes)
                raise ParsingDone

    _re_managed_object = re.compile(r"managedObject\sclass=\"(?P<OBJECT_CLASS>\w+)\"")

    def _find_managed_object(self, line):
        if self._regex_helper.search_compiled(PlanGenerate._re_managed_object, line):
            # self.current_ret['FILE_CONTENT'].update({self._regex_helper.group("OBJECT_CLASS"): {}})
            self.current_key = self._regex_helper.group("OBJECT_CLASS")


